package com.gamehub;
import com.gamehub.infrastructure.Database; import com.gamehub.application.*; import javafx.application.Application; import javafx.geometry.Insets; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage; import java.time.*;
public final class GameHubApp extends Application {
 private Database db; private UserService users; private OperationsService ops;
 public void start(Stage stage){try{db=new Database();users=new UserService(db);ops=new OperationsService(db);}catch(Exception e){new Alert(Alert.AlertType.ERROR,"Database startup failed: "+e.getMessage()).showAndWait();return;} login(stage);}
 private void login(Stage s){TextField u=new TextField();u.setPromptText("Username");PasswordField p=new PasswordField();p.setPromptText("Password");Label m=new Label();Button b=new Button("Sign in"),setup=new Button("Create first manager"),register=new Button("Create customer account");b.setOnAction(e->{try{var x=users.authenticate(u.getText(),p.getText());if(x==null)m.setText("Invalid credentials");else dashboard(s,x.id(),x.username(),x.role().name());}catch(Exception ex){m.setText(ex.getMessage());}});register.setOnAction(e->{ TextInputDialog a=new TextInputDialog(); a.setHeaderText("Customer username"); var un=a.showAndWait(); if(un.isEmpty())return; TextInputDialog q=new TextInputDialog(); q.setHeaderText("Password (8+ chars)"); var pw=q.showAndWait(); if(pw.isEmpty())return; try{users.registerCustomer(un.get(),pw.get());m.setText("Customer account created; sign in.");}catch(Exception ex){m.setText(ex.getMessage());}}); setup.setOnAction(e->{TextInputDialog a=new TextInputDialog();a.setHeaderText("Manager username");var un=a.showAndWait();if(un.isEmpty())return;TextInputDialog q=new TextInputDialog();q.setHeaderText("Password (8+ chars)");var pw=q.showAndWait();if(pw.isEmpty())return;try{users.bootstrap(un.get(),pw.get());m.setText("Manager created; sign in.");}catch(Exception ex){m.setText(ex.getMessage());}});VBox v=new VBox(12,new Label("GAMEHUB"),u,p,b,register,setup,m);v.setPadding(new Insets(40));s.setScene(new Scene(v,700,450));s.setTitle("GameHub");s.show();}
 private void dashboard(Stage s,long userId,String n,String r){VBox v=new VBox(14);v.setPadding(new Insets(24));Label status=new Label("Ready");Button stations=new Button("Manage gaming stations"),reserve=new Button("Reserve station"),session=new Button("Start/finish session"),payment=new Button("Record payment"),reports=new Button("Management reports");stations.setOnAction(e->stationDialog(status));reserve.setOnAction(e->reserveDialog(status,userId));session.setOnAction(e->sessionDialog(status));payment.setOnAction(e->paymentDialog(status,userId));reports.setOnAction(e->reportDialog(status));v.getChildren().addAll(new Label("Welcome, "+n+" · "+r),new Label("GameHub operations"),stations,reserve,session,payment,reports,status);s.setScene(new Scene(v,760,520));}
 private void stationDialog(Label status){TextInputDialog c=new TextInputDialog();c.setHeaderText("Station code");var code=c.showAndWait();if(code.isEmpty())return;TextInputDialog t=new TextInputDialog("PC");t.setHeaderText("Type");var type=t.showAndWait();if(type.isEmpty())return;TextInputDialog rate=new TextInputDialog("500");rate.setHeaderText("Hourly rate in PKR");var rr=rate.showAndWait();if(rr.isEmpty())return;try{ops.addStation(code.get(),type.get(),Long.parseLong(rr.get())*100);status.setText(String.join("\n",ops.stations()));}catch(Exception e){status.setText(e.getMessage());}}
 private void reserveDialog(Label status,long userId){TextInputDialog st=new TextInputDialog("1");st.setHeaderText("Station id");var a=st.showAndWait();if(a.isEmpty())return;try{long id=ops.reserve(userId,Long.parseLong(a.get()),Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200));status.setText("Reservation confirmed #"+id);}catch(Exception e){status.setText(e.getMessage());}}
 private void sessionDialog(Label status){TextInputDialog r=new TextInputDialog("1");r.setHeaderText("Reservation id to start");var a=r.showAndWait();if(a.isEmpty())return;try{long id=ops.startSession(Long.parseLong(a.get()));status.setText("Session active #"+id+". Use finish with charge through this action again when integrated.");}catch(Exception e){status.setText(e.getMessage());}}
 private void paymentDialog(Label status,long userId){TextInputDialog a=new TextInputDialog("1000");a.setHeaderText("Amount PKR");var x=a.showAndWait();if(x.isEmpty())return;try{long id=ops.recordPayment(userId,Long.parseLong(x.get())*100,"CASH","manual");status.setText("Payment settled #"+id);}catch(Exception e){status.setText(e.getMessage());}}
 private void reportDialog(Label status){try{status.setText("Users: "+ops.reportCount("users")+" | Stations: "+ops.reportCount("gaming_stations")+" | Reservations: "+ops.reportCount("reservations")+" | Payments: "+ops.reportCount("payments"));}catch(Exception e){status.setText(e.getMessage());}}
 public void stop(){try{if(db!=null)db.close();}catch(Exception ignored){}} public static void main(String[]a){launch(a);}
}

